package com.cartalaap.marketplace;
import java.time.Instant;import com.cartalaap.user.User;import jakarta.persistence.Column;import jakarta.persistence.Entity;import jakarta.persistence.FetchType;import jakarta.persistence.GeneratedValue;import jakarta.persistence.GenerationType;import jakarta.persistence.Id;import jakarta.persistence.JoinColumn;import jakarta.persistence.ManyToOne;import jakarta.persistence.PrePersist;import jakarta.persistence.Table;import jakarta.persistence.UniqueConstraint;
@Entity @Table(name="marketplace_reports",uniqueConstraints=@UniqueConstraint(columnNames={"listing_id","reporter_id"})) public class MarketplaceReport{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="listing_id")private MarketplaceListing listing;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="reporter_id")private User reporter;@Column(nullable=false,length=500)private String reason;@Column(name="created_at")private Instant createdAt;protected MarketplaceReport(){}public MarketplaceReport(MarketplaceListing listing,User reporter,String reason){this.listing=listing;this.reporter=reporter;this.reason=reason;}@PrePersist void onCreate(){createdAt=Instant.now();}}
